export function readMaxConcurrentRooms(raw: string | undefined) {
  const value = Number(raw);
  return raw !== undefined && raw.trim() !== "" && Number.isInteger(value) && value > 0
    ? value
    : DEFAULT_MAX_CONCURRENT_ROOMS;
}
