class Player extends Schema {
  runModifiers: RunModifiers = [];
  ownedCardIds: string[] = [];
  /** Satin alinan her sey; fiyat artisi ve stok limiti bunun uzerinden isler. */
  ownedShopItemIds: string[] = [];
  /** Alinmis ama henuz bir kuleye takilmamis esyalar. */
  inventoryItemIds: string[] = [];
  /** Altinla alinmis ek isciler; uzmanlik ilk kalici secimde belirlenir. */
  /**
   * Alinmis isciler; secilen uzmanligi ve kademesiyle.
   *
   * Tek liste tutuluyor cunku fiyat sayaci **ortak**: normal ya da gelismis,
   * her alim bir sonrakini pahalilastiriyor. Ayri listeler tutmak gelismis
   * isciyi normal alimlarla ucuza getirmenin yolunu acardi.
   */
  hiredWorkers: HiredWorker[] = [];
  /** XP ile acilan ortak isci gelisim agaci; tum ayni rol hucrelerine uygulanir. */
  workerSkillIds: WorkerSkillId[] = [];
  shopOffers: ShopItem[] = [];
  shopRerolls = 0;
  nexusShieldCharges = 0;
  /**
   * Vadeli Mevduat (esyanin `deposit` alani): her alimin odenecegi dalga ve
   * tutari. `dueWave` dalgasi tamamlaninca, dalga sonu primleriyle birlikte
   * odenip listeden dusuyor.
   */
  goldDeposits?: Array<{ dueWave: number; amount: number }> = [];

  /**
   * Odadaki sabit yuva (0-3); katilista bos olan en kucuk sayi.
   *
   * Hasar olayi vuranini bununla soyluyor. Kayitla birlikte yasiyor: yeniden
   * baglanan oyuncu ayni kaydi, dolayisiyla ayni yuvayi aliyor.
   */
  slot = 0;
  @type("string") name = "";
  @type("string") characterId: CharacterId = "warrior";
  @type("boolean") ready = false;
  @type("boolean") connected = true;
  @type("number") gold = PLAYER_START_GOLD;
  @type("number") goldSpent = 0;
  @type("number") experience = 0;
  @type("number") towersBuilt = 0;
  @type("number") ultimateCharge = 0;
  /** Altinla alinmis ulti gucu kademesi; hasar carpani buradan cikar. */
  @type("number") ultimatePower = 0;
  @type("number") skill1CooldownMs = 0;
  @type("number") skill2CooldownMs = 0;
  @type("number") skill3CooldownMs = 0;
  @type("number") reputation = 0;
  @type("number") authorityChain = 0;
  @type("number") authorityQuality = 0;
  @type("number") approval = 0;
  @type("number") stress = 0;
  @type("number") currentWaveApproval = 0;
  @type("number") lastWaveApproval = -1;
  /** Serilerin hangi tarafa yazilacagi; oyuncunun bari surdugu direksiyon. */
  melisStance: MelisStance = "approval";
}

class MatchState extends Schema {
  @type({ map: Player }) players = new MapSchema<Player>();
}

type JoinOptions = {
  playerName?: string;
  characterId?: CharacterId;
  roomName?: string;
  mapScale?: MapScale;
  mapData?: EditableMapData;
  autoStart?: boolean;
  creative?: boolean;
  /** Ogretici asamasi; yalnizca `autoStart` ile (tek kisilik oda) gecerli. */
  tutorial?: boolean;
  stage?: number;
  /**
   * Istemcinin anladigi tel surumu (`WIRE_DELTA_PROTOCOL`). Yoksa eski
   * istemci: oyuncu ve isci kayitlarini her karede tam bekliyor.
   */
  wireDelta?: number;
  /**
   * Solo odanin sahip sirri: kurulumda istemcinin urettigi rastgele metin.
   * Pencereden sonra kimlikle geri donus bunu gostermek zorunda.
   */
  ownerSecret?: string;
};

type PlaceTowerMessage = {
  definitionId?: string;
  x?: number;
  y?: number;
  orientation?: TowerOrientation;
};

type UpgradeTowerMessage = {
  towerId?: string;
};

type SellTowerMessage = {
  towerId?: string;
};

type UseSkillMessage = {
  slot?: number;
  x?: number;
  y?: number;
  /** Metal Kalkan'in ucu (dunya koordinati); baslangici `x`/`y`. */
  x2?: number;
  y2?: number;
  towerId?: string;
  /** Execute'un hedefi: istemcinin dokundugu dusmanin kimligi. */
  enemyId?: string;
  commandTier?: ZeynepCommandTier;
};

type UseUltimateMessage = {
  mode?: "attack" | "repair";
  /** Zeynep ultisinin patlayacagi sutun. */
  column?: number;
  /** Zeynep: dokunusun dunya y'si; beden sutunun o hizasina ucuyor. */
  y?: number;
};

/**
 * Duvar cizgisinin ayrilmis tek parcasi (merkez ve ayrilan bedel). "Tumunu
 * Onar" rotasinin duraklari da bu bicimde: `towerId` onarilacak yapi,
 * `standoffCells` o yapinin boyuna gore durus mesafesi.
 */
type OperatorBodyWallSegment = { x: number; y: number; cost: number; towerId?: string; standoffCells?: number };

/**
 * Bedenin kuyrugundaki is. `x`/`y` isin yeri (kare, yapi, dusman, sutun);
 * beden onun `standoffCells` kadar yaninda duruyor. `reservedGold` komut
 * aninda ayrilan ve henuz harcanmamis altin; varista ya da iadede geri konuyor.
 */
type OperatorBodyTask = {
  kind: OperatorBodyTaskKind;
  x: number;
  y: number;
  standoffCells: number;
  standX?: number;
  standY?: number;
  /** Duruş noktasinin ait oldugu duvar parcasi. */
  standIndex?: number;
  reservedGold: number;
  /** Varista isleyiciye aynen giden mesaj. */
  message: Record<string, unknown>;
  tutorial?: TutorialActionId;
  creative?: boolean;
  /** Kule kontenjani tutan kurulum. */
  slot?: boolean;
  segments?: OperatorBodyWallSegment[];
  segmentIndex?: number;
  wallStats?: { requested: number; placed: number; skippedZone: number; skippedBlocked: number; skippedGold: number };
  /** "Tumunu Onar": rotada simdiye kadar onarilanlar (ozet tek toast). */
  repairStats?: { count: number; cost: number; towerIds: string[] };
  towerIdsBefore?: Set<string>;
  towerId?: string;
  skillSlot?: number;
  enemyId?: string;
  /** Ulti bulundugu yerde atiliyor (AttackLord). */
  inPlace?: boolean;
  /**
   * Komutun verildigi kurulum arasi: kurulumda verilen ve dalga basladiktan
   * sonra varan yapi da o kurulumun yapisi sayiliyor (iade kurali).
   */
  setupSession?: number;
};

type OperatorBodyModel = {
  ownerId: string;
  characterId: CharacterId;
  x: number;
  y: number;
  hp: number;
  maxHp: number;
  state: OperatorBodyState;
  tasks: OperatorBodyTask[];
  /** Is pozunun bitisi (duvar saati); o ana kadar sonraki goreve gecilmiyor. */
  workUntil: number;
  workX?: number;
  workY?: number;
  /** Son hasar ani (duvar saati); onarim gecikmesi buradan. */
  lastDamageAt: number;
  restX?: number;
  restY?: number;
  restAnchorX?: number;
  restAnchorY?: number;
  restCheckAt: number;
  dead: boolean;
};

/**
 * Bir ultinin karnesi: ne kadar dusmana indi, kacini oldurdu.
 *
 * Aninda sonuclanan ulti (sutun, meteor, kilit alan, can dalgasi) atis aninda
 * raporlaniyor. Drone'lu ve sureli olanlar acik kaliyor ve etki bitince
 * raporlaniyor; atisi hicbir sey beklemiyor.
 */
type UltimateReport = {
  ownerId: string;
  kind: UltimateResultKind;
  hits: number;
  kills: number;
  /** Zeynep sutunu: atis aninda en kalabalik sutunun yakalayacagi dusman. */
  best?: number;
  /** Zeynep sutunu: atis aninda secilen sutunda vurulabilir dusman (nisan). */
  aim?: number;
  /** Tamir ve can dalgasi: usse gercekten donen can. */
  heal?: number;
  /** Atakan: bu atisin henuz dusmeyen drone'lari; hepsi bitince rapor gidiyor. */
  droneIds?: Set<string>;
  /**
   * Atakan: bu atisin sirasi gelmemis drone'lari (`pendingAtakanDrones`).
   * Karne bunlar da cikip (ya da atlanip) dusmeden gitmiyor.
   */
  pendingDrones?: number;
  /** Sureli ulti (Kabus, Sempati): bu andan sonra rapor gidiyor. */
  until?: number;
  /** Sempati: baga takilip kanayan dusmanlar; olumler bunlardan sayiliyor. */
  markedIds?: Set<string>;
};

/**
 * AttackLord ultisinin sirasi gelmemis drone'u.
 *
 * Kule kimligi tutuluyor, kule degil: sirasini beklerken satilan kulenin
 * drone'u cikmiyor. Hasar atistaki ulti gucuyle; hedef ve cikis noktasi
 * (beden ya da kule) cikis aninda seciliyor.
 */
type PendingAtakanDrone = {
  towerId: string;
  repairNexus: boolean;
  damage: number;
  /** Cikisa kalan oyun suresi (ms); drone omru gibi `updateDrones` sayiyor. */
  delayMs: number;
  report: UltimateReport;
};

/**
 * Dusmandaki durum kaydi: paylasilan kayit ve onu son uygulayan kulesiz
 * etkinin kaynagi.
 */
type EnemyStatusState = StatusEffectRuntimeState & {
  /**
   * Durumu son uygulayan kulesiz etki (Sempati kanamasi: `ultimate:sympathy`).
   * Kule uygulamasi yazmiyor. `applyTowerStatusEffect` her uygulamada yeni
   * kayit kurdugu icin sonraki uygulama alani dusuruyor: tikin gucu ve
   * kaynagi son uygulayaninki (butun kanamalar `refresh`).
   */
  originSourceId?: string;
};

type KillStreakLock = {
  unlockAt: number;
  wave: number;
};

const ARMOR_BREAK_MARKER_MS = 3000;

type PingMessage = {
  sentAt?: number;
};

type LinkServerMessage = {
  serverTowerId?: string;
  targetTowerId?: string;
};

type TowerModeMessage = {
  towerId?: string;
  mode?: "approval" | "stress" | "standby";
};

